#define main historical_main
#include "../glu-cuda/main.cu"
#undef main
#define CK(x) do{cudaError_t e=(x);if(e!=cudaSuccess){fprintf(stderr,"CUDA %s\n",cudaGetErrorString(e));exit(2);}}while(0)
struct Case{int m,s,n;float*out;std::vector<float>expected;};
int main(int argc,char**argv){int repeat=argc>1?atoi(argv[1]):100;if(repeat<1)return 2;int dim=32;std::vector<float>input(dim*dim*dim);for(int i=0;i<(int)input.size();i++)input[i]=float((i*17+3)%1025)/1024.f*12.f-6.f;float*di;CK(cudaMalloc(&di,input.size()*sizeof(float)));CK(cudaMemcpy(di,input.data(),input.size()*sizeof(float),cudaMemcpyHostToDevice));std::vector<Case>cases;for(int axis:{2,0,1,2,0,1,2}){Case c;c.m=1;for(int a=0;a<axis;a++)c.m*=dim;c.s=16;c.n=1;for(int a=axis+1;a<3;a++)c.n*=dim;c.expected.resize(input.size()/2);ComputeGlu(c.m,c.s,c.n,input.data(),c.expected.data());CK(cudaMalloc(&c.out,c.expected.size()*sizeof(float)));glu_kernel<<<64,256>>>(c.m,c.s,c.n,di,c.out);cases.push_back(c);}CK(cudaDeviceSynchronize());bool allok=true;for(int trial=1;trial<=5;trial++){double seconds=0,ma=0;std::vector<float>out;bool ok=true;for(auto&c:cases){CK(cudaDeviceSynchronize());auto start=std::chrono::steady_clock::now();for(int rep=0;rep<repeat;rep++)glu_kernel<<<64,256>>>(c.m,c.s,c.n,di,c.out);CK(cudaDeviceSynchronize());seconds+=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/repeat;std::vector<float>got(c.expected.size());CK(cudaMemcpy(got.data(),c.out,got.size()*sizeof(float),cudaMemcpyDeviceToHost));for(int i=0;i<(int)got.size();i++){ma=fmax(ma,fabs(got[i]-c.expected[i]));ok&=std::isfinite(got[i])&&fabs(got[i]-c.expected[i])<=1e-3;}out.insert(out.end(),got.begin(),got.end());}allok&=ok;char file[80];sprintf(file,"glu_trial%d.bin",trial);FILE*f=fopen(file,"wb");fwrite(out.data(),sizeof(float),out.size(),f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%.12g,\"max_rel_error\":0,\"timing_region\":\"sum_seven_original_axis_loop_GLU_operations_transfer_excluded\",\"jit_excluded\":true,\"internal_repeats\":%d,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,seconds,ok?"true":"false",out.size(),ma,repeat,file,out.size());}for(auto&c:cases)CK(cudaFree(c.out));CK(cudaFree(di));puts(allok?"PASS":"FAIL");return allok?0:1;}
